def orbit8(r,c):
 return {(r,c),(c,23-r),(23-r,23-c),(23-c,r),(r,23-c),(23-r,c),(c,r),(23-c,23-r)}
out=[row[:] for row in g]; problems=[]
for r in range(24):
 for c in range(24):
  if g[r][c]==2:
   cells=orbit8(r,c); vals=[g[a][b] for a,b in cells if g[a][b]!=2]
   if not vals or len(set(vals))!=1: problems.append((r,c,vals,cells))
   else: out[r][c]=vals[0]
len(problems),problems[:4],sum(v==2 for row in out for v in row),all(out[r][c]==out[c][r] for r in range(24) for c in range(24))
